#include<bits/stdc++.h>
using namespace std;
int n,k;string s;
void solve(){
	cin>>n>>k>>s;
	int ans=0;
	for(int i=0;i<n;i++){
		if(s[i]=='0'){
			int ok=1;
			for(int j=max(0,(int)i-k);j<i;j++){
				if(s[j]=='1'){
					ok=0;
					break;
				}
			}
			ans+=ok;
		}
	}
	cout<<ans<<endl;
}
int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0),cout.tie(0);
	int T;cin>>T;
	for(;T--;)solve();
	return 0;
}

#include<bits/stdc++.h>
#define ll long long

using namespace std;

const int MAXN = 1e5 + 10;

int n;
int a[MAXN], b[MAXN];

int main() {
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        for (int i = 1; i <= n; ++i) cin >> a[i];
        for (int i = 1; i <= n; ++i) cin >> b[i];
        ll mx = 0, mn = 0;
        for (int i = 1; i <= n; ++i) {
            ll new_mx = max(mx - a[i], b[i] - mn);
            ll new_mn = min(mn - a[i], b[i] - mx);
            mx = new_mx, mn = new_mn;
        }
        cout << mx << endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int mxn=2e5+5;
set<int>s;
map<int,int>u;
int n,a[mxn],k;
void solve(){
	s.clear(),u.clear();
	cin>>n>>k;
	for(int i=1;i<=n;i++)cin>>a[i],s.insert(a[i]),u[a[i]]=1;
	vector<int>ans;ans.clear();
	while(s.size()){
		int t=*s.begin();
		ans.push_back(t);
		s.erase(s.begin());
		for(int cur=t;cur<=k;cur+=t){
			if(!u[cur]){
				cout<<"-1\n";
				return;
			}
			auto t=s.find(cur);
			if(t!=s.end())s.erase(t);
		}
	}
	cout<<ans.size()<<'\n';
	for(int i:ans)cout<<i<<' ';cout<<'\n';
}
int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0),cout.tie(0);
	int T=1;
	cin>>T;
	for(;T--;)solve();
	return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;
const int inf=1e9+7;
const int mxb=64,mxk=32;
int dp[mxb+2][mxk+2][2];
void Min(int&x,int y){x=min(x,y);}
void solve(){
	int n,k;cin>>n>>k;
	int pc=__builtin_popcount(n);
	if(n==0){
		cout<<max(0ll,k-1)<<'\n';
		return;
	}
	if(k>=32){
		cout<<k+pc-1<<'\n';
		return;
	}
	for(int i=0;i<=mxb;i++)for(int j=0;j<=k;j++)dp[i][j][0]=dp[i][j][1]=inf;
	dp[0][0][0]=0;
	for(int i=0;i<mxb;i++){
		int ni=(n>>i)&1ll;
		for(int u=0;u<=k;u++)for(int c=0;c<=1;c++){
			int cur=dp[i][u][c];
			if(cur>=inf)continue;
			{
				int sum=ni+c,bit=sum&1,nc=sum>>1;
				Min(dp[i+1][u][nc],cur+bit);		
			}
			if(u+1<=k){
				int sum=ni+1+c,bit=sum&1,nc=sum>>1;
				Min(dp[i+1][u+1][nc],cur+bit);
			}
		}
	}
	int bst=inf;
	for(int u=0;u<=k;u++)for(int c=0;c<=1;c++){
		int val=dp[mxb][u][c];
		if(val<inf)Min(bst,val+c);
	}
	int ans=k+pc-bst;
	cout<<ans<<'\n';
}
signed main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0),cout.tie(0);
	int T;cin>>T;
	for(;T--;)solve();
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int mxn=40004;
int n,a[mxn],pos[mxn];
int mirror(int x){
	return n-x+1;
}
pair<int,int>ask(int x,int y){
	cout<<"? "<<x<<' '<<y<<endl;
	fflush(stdout);
	int u,v;cin>>u>>v;
	return {u,v};
}
void solve(){
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		pos[a[i]]=i;
	}
	if(n%2==1){
		int mid=(n+1)/2;
		while(pos[mid]!=mid){
			auto p=ask(mid,pos[mid]);
			int u=p.first,v=p.second;
			swap(a[u],a[v]);
			pos[a[u]]=u,pos[a[v]]=v;
		}
	}
	for(int i=1;i<=n/2;i++){
		int x=pos[i],y=pos[mirror(i)];
		if(x+y!=n+1){//not mirror
			auto p=ask(x,mirror(y));
			int u=p.first,v=p.second;
			swap(a[u],a[v]);
			pos[a[u]]=u,pos[a[v]]=v;
		}
	}
	for(int i=1;i<=n/2;i++){
		while(pos[i]!=i or pos[mirror(i)]!=mirror(i)){
			if(pos[i]!=i){
				auto p=ask(i,pos[i]);
				int u=p.first,v=p.second;
				swap(a[u],a[v]);
				pos[a[u]]=u,pos[a[v]]=v;				
			}else{
				auto p=ask(mirror(i),pos[mirror(i)]);
				int u=p.first,v=p.second;
				swap(a[u],a[v]);
				pos[a[u]]=u,pos[a[v]]=v;	
			}
		}
	}
	cout<<"!"<<endl;
	fflush(stdout);
}
int main(){
	int T=1;
	cin>>T;
	for(;T--;)solve();
	return 0;
}

#include<bits/stdc++.h>
#define ll long long
using namespace std;
const int mxn=2e5+5;
const int B=512;
int T,f[B+3][mxn],n,a[mxn],q;
ll sum[mxn],N=1000000001;
int l_[mxn],r_[mxn],x_[mxn];
int id[mxn];
void solve(){
	cin>>n>>q;
	vector<int>v;v.clear();
	for(int i=1;i<=n;i++)
		cin>>a[i],
		sum[i]=sum[i-1]+a[i];
	for(int i=1;i<=q;i++)
		cin>>l_[i]>>r_[i]>>x_[i],
		v.push_back(x_[i]);
	v.push_back(0);
	v.push_back(1000000008);
	sort(v.begin(),v.end());
	v.erase(unique(v.begin(),v.end()),v.end());
	for(int i=1;i<=q;i++)
		id[i]=lower_bound(v.begin(),v.end(),x_[i])-v.begin();
	for(int i=1;i<=B;i++){
		int k=0;
		for(int j=n-i;j>=0;j--)
			for(;v[k]<=min(sum[j+i]-sum[j],N);k++)
				f[i][k]=j+1;
	}
	for(int t=1;t<=q;t++){
		int l,r,x,cnt=0;
		l=l_[t],r=r_[t],x=x_[t];
		for(int i=1;i<=B;i++)
			if(f[i][id[t]]>=l){
				int w=min(r-l+1,f[i][id[t]]-l+i)/i;
				cnt+=w;
				l+=w*i;
			}l--;
		while(1){
			if(sum[r]-sum[l]<x){
				cout<<cnt<<' '<<sum[r]-sum[l]<<'\n';
				break;
			}cnt++;
			int t=x,lo=l-1,hi=n+1,md;
			ll req=sum[l]+t;
			for(;lo<hi-1;){
				md=lo+hi>>1;
				if(sum[md]<req)lo=md;
				else hi=md;
			}
			l=hi;
		}
	}
	for(int i=0;i<max(n,(int)v.size())+3;i++)sum[i]=0;
	for(int j=0;j<B+3;j++)for(int i=0;i<max(n,(int)v.size())+3;i++)f[j][i]=0;
}
signed main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0),cout.tie(0);
	T=1;cin>>T;
	while(T--)solve();
	return 0;
}
